package com.ruoyi.business.ai.capability.project;
import java.util.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.stereotype.Component;import com.ruoyi.business.ai.capability.*;import com.ruoyi.business.service.IBusinessProjectService;import static com.ruoyi.business.ai.capability.AiCapabilityInputs.*;
@Component public class RetireProjectRoutineCapability implements AiConfirmableCapability{private final IBusinessProjectService service;@Autowired public RetireProjectRoutineCapability(IBusinessProjectService s){service=s;}public String code(){return "project.routine.retire";}public String description(){return "停用一项持续工作计划，历史填报保留。先读取项目详情取得真实routineId；确认后执行。";}public String requiredPermission(){return "business:project:task";}public Map<String,Object> inputSchema(){Map<String,Object>s=AiSchemas.object();AiSchemas.property(s,"projectId","number","项目ID");AiSchemas.property(s,"routineId","number","持续工作ID");AiSchemas.property(s,"routineName","string","名称，仅用于确认展示");return AiSchemas.required(s,"projectId","routineId");}public String confirmationSummary(AiCapabilityInvocation i,Map<String,Object>in){return "停用持续工作“"+(text(in.get("routineName")).isEmpty()?"ID "+number(in.get("routineId")):text(in.get("routineName")))+"”，历史填报继续保留";}public Map<String,Object> executeConfirmed(AiCapabilityInvocation i,Map<String,Object>in){service.removeRoutine(number(in.get("projectId")),number(in.get("routineId")),i.getActor().getUserId(),i.getActor().getUserName(),true);Map<String,Object>r=new LinkedHashMap<String,Object>();r.put("projectId",number(in.get("projectId")));r.put("routineId",number(in.get("routineId")));r.put("status","RETIRED");return r;}}
